@Service
public class UserService {
  @Autowired private UserDao userDao;
  @Resource private MailClient mailClient;
}

rules.good:
@Service
public class UserService {
  private final UserDao userDao;
  private final MailClient mailClient;

  public UserService(UserDao userDao, MailClient mailClient) {
    this.userDao = userDao;
    this.mailClient = mailClient;
  }
}

rules.bad:
@Service
public class OrderService {
  public void create(Order o) {
    this.saveItems(o);   // 同类内部调用，事务失效
  }
  @Transactional private void saveItems(Order o) { ... }   // private + 同调用，双重失效
}

rules.good:
@Service
public class OrderService {
  private final OrderItemService orderItemService;

  @Transactional(rollbackFor = Exception.class)
  public void create(Order o) {
    orderItemService.saveItems(o);   // 跨 Bean 调用，走代理
  }
}

if (user == null) throw new BizException(ErrorCode.USER_NOT_FOUND, "用户不存在");

// 自定义异常继承 RuntimeException，携带错误码
public class BizException extends RuntimeException {
  private final ErrorCode code;
}

rules.bad:
@Transactional(rollbackFor = Exception.class)
public void pay(Long id) {
  orderDao.update(id);
  payClient.invoke(id);       // 事务内远程调用，连接被占住
}

rules.good:
public void pay(Long id) {
  PayResult r = payClient.invoke(id);        // 事务外远程调用
  orderService.markPaid(id, r);              // 事务内只做本地写
}

